  'Sans pub jusqu\'au {d}': {'en': 'Ad-free until {d}', 'es': 'Sin anuncios hasta el {d}', 'de': 'Keine Werbung bis {d}', 'ar': 'بدون إعلانات حتى {d}', 'pt': 'Sem anúncios até {d}', 'zh': '无广告至 {d}', 'sw': 'Bila matangazo hadi {d}'},
